//! 🧫️ Shared authored SFNT admission, outlines and kerning agree with ttf-parser, rustybuzz and pixels and retain original backing through funded close.
use super::*;
use semio_framework_2d_text_font_testing::{bytes,close};
#[global_allocator]
static FONT_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
struct OraclePath(tiny_skia::PathBuilder);
impl ttf_parser::OutlineBuilder for OraclePath{fn move_to(&mut self,x:f32,y:f32){self.0.move_to(x,y);}fn line_to(&mut self,x:f32,y:f32){self.0.line_to(x,y);}fn quad_to(&mut self,x1:f32,y1:f32,x:f32,y:f32){self.0.quad_to(x1,y1,x,y);}fn curve_to(&mut self,x1:f32,y1:f32,x2:f32,y2:f32,x:f32,y:f32){self.0.cubic_to(x1,y1,x2,y2,x,y);}fn close(&mut self){self.0.close();}}
fn rendered(path:Option<tiny_skia::Path>,em:u16)->tiny_skia::Pixmap{let mut image=tiny_skia::Pixmap::new(128,96).unwrap();if let Some(path)=path{let paint=tiny_skia::Paint::default();let scale=40.0/f32::from(em);image.fill_path(&path,&paint,tiny_skia::FillRule::Winding,tiny_skia::Transform::from_row(scale,0.0,0.0,-scale,8.0,48.0),None);}image}
#[test]
fn font_admission_shared_unicode_and_metrics_match_ttf_parser(){let rows:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for row in rows.as_array().unwrap(){for grant in [1,7,4096]{let source=bytes(row["font"].as_str().unwrap());let oracle=ttf_parser::Face::parse(&source,0).unwrap();let units=oracle.units_per_em();let count=oracle.number_of_glyphs();let expected:Vec<_>=row["text"].as_str().unwrap().chars().filter(|c|!matches!(c,'\r'|'\n')).map(|c|{let glyph=oracle.glyph_index(c).unwrap();(c,glyph.0,oracle.glyph_hor_advance(glyph).unwrap())}).collect();let pointer=source.as_ptr();let capacity=source.capacity();let mut job=FontFaceAdmissionJob::new(source,FontOutlineLimits::default());let mut work=0;loop{let p=job.advance(grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(job.result().is_err());}let font=job.take_result().unwrap();assert_eq!(font.source.as_ptr(),pointer);assert_eq!(font.face.units_per_em,units);assert_eq!(font.face.glyphs,count);for(c,glyph,advance)in expected{let mut cursor=FontCmapCursor::new(font.face,c as u32).unwrap();while !cursor.step(&font.source).unwrap(){}assert_eq!(cursor.result().unwrap(),glyph);assert_eq!(font_advance(font.face,&font.source,glyph).unwrap(),advance);}close(job);assert!(close(font)>=capacity);}}}
#[test]
fn font_admission_cancellation_preserves_actual_source(){let font="🚀️anta/🏛️latin/📖️regular";for stop in [0,1,2,7,20]{let source=bytes(font);let capacity=source.capacity();let mut job=FontFaceAdmissionJob::new(source,FontOutlineLimits::default());if stop>0{job.advance(stop).unwrap();}job.cancel();assert!(job.result().is_err());assert!(close(job)>=capacity);}for source in [Vec::new(),vec![0;16],vec![0;64]]{let capacity=source.capacity();let mut job=FontFaceAdmissionJob::new(source,FontOutlineLimits::default());assert!(job.advance(1).is_err());assert!(close(job)>=capacity);}}
#[test]
fn font_outline_shared_true_contours_match_ttf_parser_pixels(){let rows:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for row in rows.as_array().unwrap(){let source=bytes(row["font"].as_str().unwrap());let pointer=source.as_ptr();let mut admission=FontFaceAdmissionJob::new(source,FontOutlineLimits::default());while !admission.advance(7).unwrap().done{}let font=admission.take_result().unwrap();for c in row["text"].as_str().unwrap().chars().filter(|c|!matches!(c,'\r'|'\n')).collect::<std::collections::BTreeSet<_>>(){let oracle=ttf_parser::Face::parse(&font.source,0).unwrap();let glyph=oracle.glyph_index(c).unwrap();let mut reference=OraclePath(tiny_skia::PathBuilder::new());oracle.outline_glyph(glyph,&mut reference);let expected=rendered(reference.0.finish(),font.face.units_per_em);for grant in [1,7,4096]{let mut cursor=outline::GlyphOutlineCursor::new(font.face,glyph.0,FontOutlineLimits::default());let mut work=0;loop{let p=cursor.advance(&font.source,grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}let result=cursor.take_result().unwrap();let mut path=tiny_skia::PathBuilder::new();for segment in result.segments.iter(){match segment{semio_framework_2d_engine::PathSegment::Move{to}=>path.move_to(to[0]as f32,to[1]as f32),semio_framework_2d_engine::PathSegment::Line{to}=>path.line_to(to[0]as f32,to[1]as f32),semio_framework_2d_engine::PathSegment::Quad{ctrl,to}=>path.quad_to(ctrl[0]as f32,ctrl[1]as f32,to[0]as f32,to[1]as f32),semio_framework_2d_engine::PathSegment::Close=>path.close(),_=>panic!("Unexpected glyph curve")}}let actual=rendered(path.finish(),font.face.units_per_em);assert!(actual.data().iter().zip(expected.data()).all(|(a,b)|a.abs_diff(*b)<=1),"{} {c} grant={grant}",row["name"]);assert_eq!(font.source.as_ptr(),pointer);close(cursor);close(result);}}close(admission);close(font);}}
#[test]
fn font_outline_cancelled_children_use_actual_physical_close(){let mut admission=FontFaceAdmissionJob::new(bytes("🚀️anta/🏛️latin/📖️regular"),FontOutlineLimits::default());while !admission.advance(7).unwrap().done{}let font=admission.take_result().unwrap();let oracle=ttf_parser::Face::parse(&font.source,0).unwrap();let glyph=oracle.glyph_index('Ä').unwrap();for stop in [0,1,2,7,20,100,1000]{let mut cursor=outline::GlyphOutlineCursor::new(font.face,glyph.0,FontOutlineLimits::default());if stop>0{cursor.advance(&font.source,stop).unwrap();}cursor.cancel();assert!(cursor.result().is_err());close(cursor);}close(admission);close(font);}
#[test]
fn font_kerning_actual_gpos_pairs_match_rustybuzz(){let rows:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for row in rows.as_array().unwrap(){let mut admission=FontFaceAdmissionJob::new(bytes(row["font"].as_str().unwrap()),FontOutlineLimits::default());while !admission.advance(7).unwrap().done{}let font=admission.take_result().unwrap();let oracle=rustybuzz::Face::from_slice(&font.source,0).unwrap();let text:Vec<_>=row["kerningText"].as_str().unwrap().chars().collect();for pair in text.windows(2).filter(|pair|!pair.iter().any(|c|matches!(c,'\r'|'\n'))){let mut buffer=rustybuzz::UnicodeBuffer::new();buffer.push_str(&pair.iter().collect::<String>());buffer.guess_segment_properties();let features:Vec<_>=[b"liga",b"clig",b"calt"].into_iter().map(|tag|rustybuzz::Feature{tag:ttf_parser::Tag::from_bytes(tag),value:0,start:0,end:u32::MAX}).collect();let expected=rustybuzz::shape(&oracle,&features,buffer);assert_eq!(expected.glyph_infos().len(),2);let left=expected.glyph_infos()[0].glyph_id as u16;let right=expected.glyph_infos()[1].glyph_id as u16;let reference=expected.glyph_positions().iter().map(|p|p.x_advance).sum::<i32>()-i32::from(font_advance(font.face,&font.source,left).unwrap())-i32::from(font_advance(font.face,&font.source,right).unwrap());for grant in [1,7,4096]{let mut cursor=kerning::FontKerningCursor::new(font.face,left,right,1000000000);let mut work=0;loop{let p=cursor.advance(&font.source,grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}assert_eq!(cursor.result().unwrap(),reference,"{} pair={pair:?} grant={grant}",row["name"]);close(cursor);}}close(admission);close(font);}}
